package com.yskj.shopify.web.service;
import com.alibaba.fastjson.JSONObject;import com.yskj.dao.dto.org.LoginedUser;import com.yskj.shopify.contract.connection.ICustomStoreConnectionService;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
class CustomStoreConnectionClientTest {
 JSONObject view(String state,long version){var r=new JSONObject();r.put("schemaVersion",1);r.put("shopDomain","custom.example");r.put("provider","CUSTOM");r.put("connectorType","AUW_V2");r.put("state",state);r.put("version",version);r.put("featureEnabled",true);r.put("configured",true);return r;}
 LoginedUser user(){var u=new LoginedUser();u.setId("session-user");u.setDomainid("tenant-a");u.setApplicationid("app");u.setAclNameList("[营销管理端访问]||[店铺治理]");return u;}
 @Test void sendsOnlyServerSessionIdentityAndFixedSurface(){var remote=mock(ICustomStoreConnectionService.class);when(remote.getConnection(any())).thenReturn(new JSONObject());new CustomStoreConnectionClient(remote).status(user(),"custom.example");var captured=org.mockito.ArgumentCaptor.forClass(JSONObject.class);verify(remote).getConnection(captured.capture());assertThat(captured.getValue().getString("surface")).isEqualTo("MERCHANT");assertThat(captured.getValue().getJSONObject("user").getString("id")).isEqualTo("session-user");assertThat(captured.getValue().getJSONObject("user").getString("domainid")).isEqualTo("tenant-a");}
 @Test void viewNeverCopiesTokenOrArbitraryRemoteFields(){var remote=mock(ICustomStoreConnectionService.class);var status=view("VERIFIED",0);status.put("featureEnabled",true);status.put("configured",true);status.put("canConfigure",true);status.put("apiToken","sensitive");status.put("message","sensitive");status.put("unknown","sensitive");when(remote.getConnection(any())).thenReturn(status);var view=new CustomStoreConnectionClient(remote).status(user(),"custom.example");assertThat(view.toJSONString()).doesNotContain("sensitive","apiToken","unknown");assertThat(view.getString("state")).isEqualTo("VERIFIED");assertThat(view.getBooleanValue("syncEnabled")).isFalse();assertThat(view.getString("signatureState")).isEqualTo("NOT_VERIFIED");}
 @Test void remoteFailureDoesNotExposeMessage(){var remote=mock(ICustomStoreConnectionService.class);when(remote.getConnection(any())).thenThrow(new IllegalStateException("token=private"));var view=new CustomStoreConnectionClient(remote).status(user(),"custom.example");assertThat(view.toJSONString()).doesNotContain("private");assertThat(view.getBooleanValue("available")).isFalse();}
 @Test void malformedDomainsNeverReachRemote(){var remote=mock(ICustomStoreConnectionService.class);var client=new CustomStoreConnectionClient(remote);for(String shop:new String[]{"https://custom.example","custom.example?token=x","../secret"})assertThatThrownBy(()->client.status(user(),shop)).isInstanceOf(IllegalArgumentException.class);verifyNoInteractions(remote);}
 @Test void invalidPrincipalNeverReachesRemote(){var remote=mock(ICustomStoreConnectionService.class);assertThatThrownBy(()->new CustomStoreConnectionClient(remote).status(null,"custom.example")).isInstanceOf(IllegalArgumentException.class);verifyNoInteractions(remote);}
 @Test void merchantCannotForwardAnyConfigurationMutation(){var remote=mock(ICustomStoreConnectionService.class);var client=new CustomStoreConnectionClient(remote);assertThatThrownBy(()->client.save(user(),"custom.example","u","s","e","secret",0)).isInstanceOf(IllegalStateException.class);assertThatThrownBy(()->client.saveSourceProfile(user(),"custom.example","CUSTOM","AUW_V2",0)).isInstanceOf(IllegalStateException.class);verifyNoInteractions(remote);}
 @Test void probeUsesOnlyAuthenticatedIdentityAndExpectedVersion(){var remote=mock(ICustomStoreConnectionService.class);when(remote.testConnection(any())).thenReturn(view("VERIFIED",3));new CustomStoreConnectionClient(remote).probe(user(),"custom.example",3);verify(remote).testConnection(argThat(r->r.getJSONObject("payload").size()==1&&r.getJSONObject("payload").getLongValue("expectedVersion")==3));}
 @Test void crossShopOrProtocolRepliesFailClosed(){for(String field:new String[]{"shopDomain","provider","connectorType","schemaVersion"}){var remote=mock(ICustomStoreConnectionService.class);var raw=view("VERIFIED",0);raw.put(field,"wrong");when(remote.getConnection(any())).thenReturn(raw);assertThat(new CustomStoreConnectionClient(remote).status(user(),"custom.example").getBooleanValue("available")).isFalse();}}
 @Test void unexpectedCommandStateAndVersionCannotClaimSuccess(){var remote=mock(ICustomStoreConnectionService.class);when(remote.saveConnection(any())).thenReturn(view("DISABLED",4));when(remote.testConnection(any())).thenReturn(view("VERIFIED",4));var client=new CustomStoreConnectionClient(remote);assertThatThrownBy(()->client.save(user(),"custom.example","u","s","e","secret",3)).isInstanceOf(IllegalStateException.class);assertThatThrownBy(()->client.probe(user(),"custom.example",3)).isInstanceOf(IllegalStateException.class);}
 @Test void sourceProfileUsesPersistedFamilyEvenForShopifyLookingDomain(){var remote=mock(ICustomStoreConnectionService.class);var p=profile("CUSTOM","NONE");p.put("shopDomain","demo.myshopify.com");when(remote.getSourceProfile(any())).thenReturn(p);var result=new CustomStoreConnectionClient(remote).sourceProfile(user(),"demo.myshopify.com");assertThat(result.getString("sourceType")).isEqualTo("CUSTOM");assertThat(result.getString("connectorKey")).isEqualTo("NONE");verify(remote).getSourceProfile(argThat(r->"MERCHANT".equals(r.getString("surface"))));}
 JSONObject profile(String source,String connector){var p=new JSONObject();p.put("schemaVersion",1);p.put("shopDomain","custom.example");p.put("sourceType",source);p.put("connectorKey",connector);p.put("connectorStatus",connector.equals("NONE")?"UNSELECTED":connector.equals("SHOPLINE_PENDING")?"PLANNED":"READY");p.put("legacy",true);p.put("profileVersion",0);p.put("selectionAvailable",true);p.put("canSelect",true);return p;}
 @Test void profileRejectsCrossShopInvalidPairVersionAndRemoteSecrets(){for(String field:new String[]{"shopDomain","sourceType","connectorKey","profileVersion"}){var remote=mock(ICustomStoreConnectionService.class);var p=profile("CUSTOM","NONE");p.put(field,"wrong");p.put("apiToken","secret");when(remote.getSourceProfile(any())).thenReturn(p);var result=new CustomStoreConnectionClient(remote).sourceProfile(user(),"custom.example");assertThat(result.getBooleanValue("available")).isFalse();assertThat(result.toJSONString()).doesNotContain("secret");}}
 @Test void readonlyViewCannotBeMadeEditableByOldBackend(){var remote=mock(ICustomStoreConnectionService.class);var raw=view("VERIFIED",1);raw.put("canConfigure",true);raw.put("canTest",true);raw.put("sourceStoreId","private-source");raw.put("datasetEpoch","private-epoch");when(remote.getConnection(any())).thenReturn(raw);when(remote.getSourceProfile(any())).thenReturn(profile("CUSTOM","AUW_V2"));var client=new CustomStoreConnectionClient(remote);var v=client.status(user(),"custom.example");assertThat(v.getBooleanValue("canConfigure")).isFalse();assertThat(v.getBooleanValue("canTest")).isTrue();assertThat(v.toJSONString()).doesNotContain("private-source","private-epoch");assertThat(client.sourceProfile(user(),"custom.example").getBooleanValue("canSelect")).isFalse();raw.put("canTest",false);assertThat(client.status(user(),"custom.example").getBooleanValue("canTest")).isFalse();raw.put("canTest","true");assertThat(client.status(user(),"custom.example").getBooleanValue("canTest")).isFalse();raw.remove("canTest");assertThat(client.status(user(),"custom.example").getBooleanValue("canTest")).isTrue();raw.put("configured",false);assertThat(client.status(user(),"custom.example").getBooleanValue("canTest")).isFalse();}

 @Test void malformedProfileFlagsAndConnectorStatusFailClosed(){var remote=mock(ICustomStoreConnectionService.class);var c=new CustomStoreConnectionClient(remote);var raw=profile("CUSTOM","NONE");raw.put("canSelect","true");when(remote.getSourceProfile(any())).thenReturn(raw);assertThat(c.sourceProfile(user(),"custom.example").getBooleanValue("available")).isFalse();raw=profile("CUSTOM","AUW_V2");raw.put("connectorStatus","PLANNED");when(remote.getSourceProfile(any())).thenReturn(raw);assertThat(c.sourceProfile(user(),"custom.example").getBooleanValue("available")).isFalse();}
 @Test void unboundLegacyProfileIsReadOnlyAndExplicit(){var remote=mock(ICustomStoreConnectionService.class);var raw=profile("CUSTOM","NONE");raw.put("bindingRequired",true);raw.put("selectionAvailable",false);raw.put("canSelect",false);when(remote.getSourceProfile(any())).thenReturn(raw);var v=new CustomStoreConnectionClient(remote).sourceProfile(user(),"custom.example");assertThat(v.getBooleanValue("available")).isTrue();assertThat(v.getBooleanValue("bindingRequired")).isTrue();assertThat(v.getBooleanValue("canSelect")).isFalse();}
}
